package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class ProductOrderTest {
 @Test public void mixedFiniteSupplyExhaustsBeforeOldestAndChecksPublicValues(){Generator g=new Generator(new Random(124));var limits=GlobalCurriculum.limits("england-primary-2021-v1",ProductOrder.ID,2);List<String> recent=new ArrayList<>();Map<String,Integer> count=new HashMap<>();for(int i=0;i<108;i++){Question q=g.next(ProductOrder.ID,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=ProductOrder.read(q);assertNotNull(v);String category=v[2]==0?"mul":v[0]==0?"zero":v[0]==v[1]?"same":"different";count.merge(category,1,Integer::sum);q.answers=new String[]{"poison"};List<String> answer=v[2]==0?List.of(""+(v[0]*v[1]),""+(v[0]*v[1])):List.of(category);assertTrue(new Checker().check(q,List.of(),answer).correct());if(v[2]==0){assertEquals(1,new Checker().check(q,List.of(),List.of(answer.get(0),""+(v[0]*v[1]+1))).index);assertTrue(q.choices.isEmpty());}else{assertEquals(3,q.choices.size());assertFalse(new Checker().check(q,List.of(),List.of(category.equals("same")?"different":"same")).correct());}HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(v[2]==0?4:5,p.size());assertTrue(p.step(0).accepts(""+v[0]));assertTrue(p.step(1).accepts(""+v[1]));assertTrue(p.step(2).accepts(""+(v[2]==0?v[0]*v[1]:v[0]/v[1])));if(v[2]==1){assertTrue(p.step(3).accepts(v[1]<v[0]?"<":v[1]>v[0]?">":"="));assertTrue(p.step(4).accepts(category));}for(int s=0;s<p.size();s++)assertFalse(p.step(s).before.matches(".*\\d.*"));}assertEquals(Map.of("mul",69,"same",3,"zero",3,"different",33),count);assertEquals(recent.get(0),g.next(ProductOrder.ID,recent,false,limits).signature());}
 @Test public void divisionUsesExactComparisonIncludingZeroAndEqualExceptions(){for(int b:List.of(2,5,10))for(int c=0;c<=12;c++){Question q=ProductOrder.make(true,b*c,b);String verdict=c==0?"zero":c==1?"same":"different";assertTrue(new Checker().check(q,List.of(),List.of(verdict)).correct());}Question q=ProductOrder.make(false,0,10);assertTrue(new Checker().check(q,List.of(),List.of("0","0")).correct());q=ProductOrder.make(true,20,5);q.prompt=q.prompt.replace("5 ÷ 20","5 ÷ 21");assertNull(ProductOrder.read(q));q=ProductOrder.make(true,20,5);q.prompt=q.prompt.replace("20 ÷ 5","21 ÷ 5").replace("5 ÷ 20","5 ÷ 21");assertNull(ProductOrder.read(q));}
 @Test public void freshOutcomeGroupsAreAvailableWithoutPredictableAlwaysDifferent(){Set<String> seen=new HashSet<>();Generator sample=new Generator(new Random(124));for(int seed=0;seed<120;seed++){Question q=sample.next(ProductOrder.ID,List.of(),true,GlobalCurriculum.limits("england-primary-2021-v1",ProductOrder.ID,2));int[] v=ProductOrder.read(q);seen.add(v[2]==0?"mul":v[0]==0?"zero":v[0]==v[1]?"same":"different");}assertEquals(4,seen.size());Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(ProductOrder.ID,2));assertFalse(GlobalCurriculum.pack(p).inGrade(ProductOrder.ID,1));}
}

